@startuml

class Employee {
  + Ssn : int
  + FirstName : string
  + LastName : string
}

abstract class CreativeEmployee {
  + OscarWinner : boolean
}

class Director {}
class Actor {}

class Technician {
  + FieldOfActivity : string
}

class Screenwriter {
  + Name : string
  + MostSuccessfulFilm : string
}

class FilmSet {
  + Location : string
}

class Film {
  + Title : string
  + YearOfRelease : int
  + Genre : Genre
}

enum Genre {
  Thriller
  Action
  Horror
  Comedy
}

class Screenplay {
  + Title : string
  + Version : string
  + Date : date
  + NumberOfScenes : int
  + Plot : string
  + BasedOnNovel : boolean
  + BasedOnConcept : boolean
}

class Novel {
  + Title : string
  + Author : string
}

class ScreenplayVersion {
  + VersionNumber : int
  + Date : date
}

FilmSet "1" -- "*" Film : Located at
Film "1" -- "*" Screenplay : Based on
Screenwriter "1" -- "*" Screenplay : Creates
Director --|> CreativeEmployee
Actor --|> CreativeEmployee
Technician --|> Employee
CreativeEmployee "0..1" -- "1" Director : Assistant to
CreativeEmployee "0..*" -- "1" Film : Works on
Film "1" -- "*" Actor : Has actor in role
Screenplay "1" -- "*" ScreenplayVersion : Has version

@enduml

